resposta:
Abaixo está um programa completo em **PyQt6** para:

- Baixar vídeos de URLs e escolher a qualidade antes de baixar (saída **MP4**);
- Converter **Vídeo → Áudio**;
- Converter **Vídeo → Vídeo**;
- Converter **Áudio → Áudio**;

Com **barra de progresso em tempo real** em cada aba. Ele usa **yt-dlp** para downloads e **ffmpeg** para conversões. Os formatos de áudio suportados são `mp3`, `wav`, `ogg`, `aac` e `alac`. Os formatos de vídeo de saída suportados são `mp4`, `avi`, `ogv`, `mkv` e `mov`.

> **Observações importantes:**
> - Exija **yt-dlp** e **ffmpeg** instalados.
> - O programa assume um **ffmpeg** recente que suporte o codec `alac`. Se der erro em ALAC, o ffmpeg pode não ter esse codec instalado.
> - Use Python **3.10+** e instale dependências com:
>   ```bash
>   pip install PyQt6 yt-dlp
>   ```

---

```python
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MultiFormat Media Converter - PyQt6
Funcoes:
  - Baixar video de URL e escolher qualidade (MP4)
  - Converter video -> audio
  - Converter video -> video
  - Converter audio -> audio
Formatos de saida:
  Videos:  MP4, AVI, OGV, MKV, MOV
  Audios:  MP3, WAV, OGG, AAC, ALAC
"""
import sys
import os
import re
import subprocess
import threading
import shutil
from pathlib import Path
from PyQt6 import QtCore, QtWidgets

# ------------------------------------------------------------------
# Configuracoes
# ------------------------------------------------------------------
HOME = Path.home()
CONVERT_OUT = HOME / "Videos" / "Converter_Media"
CONVERT_OUT.mkdir(parents=True, exist_ok=True)
VIDEO_DL_OUT = HOME / "Videos" / "Downloads"
VIDEO_DL_OUT.mkdir(parents=True, exist_ok=True)

AUDIO_EXT = {
    "mp3": "mp3", "wav": "wav", "ogg": "ogg",
    "aac": "aac", "alac": "alac",
}
VIDEO_EXT = {
    "mp4": "mp4", "avi": "avi", "ogv": "ogv",
    "mkv": "mkv", "mov": "mov",
}

# Alturas maximas permitidas para cada rotulo de qualidade
ALLOWED_QUALITIES = [
    ("240p", 480), ("360p", 720), ("480p", 854),
    ("540p", 1280), ("720p", 1280), ("1080p", 2160),
    ("1440p", 2560), ("2160p", 3456), ("4K", 3840),
]

# Regras para interpretar linhas do stderr do ffmpeg
PROG_RE = re.compile(r"Progress:\s+%(\d+)\b")
REM_RE = re.search(r"([\d.]+)/([\d.]+)\s*M", re.IGNORECASE)
TIME_RE = re.compile(r"Remaining time:\s+(\d+):\s+(\d+):\s+(\d+)")
FRAMES_RE = re.compile(r"Frames:\s+(\d+)\s*duracao:\s*([\d:\.]+)")


# ------------------------------------------------------------------
# Utilitarios
# ------------------------------------------------------------------
class Event:
    """Flag simples para cancelamento de tarefa."""
    def __init__(self):
        self._set = False

    def is_set(self):
        return self._set

    def set(self):
        self._set = True

    def clear(self):
        self._set = False


def fmt_size(v):
    """Converte bytes para KB / MB / GB."""
    if v <= 0:
        return "—"
    if v < 1_000_000:
        return f"{v / 1024:.1f} KB"
    if v < 1_000_000_000:
        return f"{v / 1_000_000:.1f} MB"
    return f"{v / 1_000_000_000:.1f} GB"


def fmt_bitrate(bps):
    """Converte bits/s para Mbps."""
    if bps is None or bps <= 0:
        return "—"
    return f"{bps / 1000:.0f} Mbps"


def to_label_height(height):
    """Altura em rotulo comum (ex.: 1080 -> '1080p')."""
    if height is None:
        return "?"
    if height == 2160:
        return "1080p"
    if height == 1440:
        return "1440p"
    if height == 1280:
        return "720p"
    if height == 854:
        return "480p"
    if height == 720:
        return "360p"
    if height == 480:
        return "240p"
    if height >= 2560:
        return "4K"
    return f"{int(height)}p"


# ------------------------------------------------------------------
# Modelo da tabela de qualidades
# ------------------------------------------------------------------
class QualityTableModel(QtWidgets.QAbstractTableModel):
    def __init__(self, rows):
        super().__init__()
        self._rows = rows
        self._headers = ["Qualidade", "Tamanho estimado", "Bitrate"]
        self.setTitle("Qualidades disponíveis")

    def rowCount(self, parent=None):
        return len(self._rows)

    def columnCount(self, parent=None):
        return 3

    def data(self, role, index):
        if role == QtCore.Qt.DisplayRole:
            row = self._rows[index.row()]
            col = index.column()
            if col == 0:
                return row["label"]
            if col == 1:
                return row["size"]
            if col == 2:
                return row["bitrate"]
            return ""
        if role == QtCore.Qt.UserRole:
            return self._rows[index.row()].get("meta")
        return None

    def headerData(self, role, section, align=None):
        if role == QtCore.Qt.RoleHeaderRole:
            return self._headers[section]
        return None


# ------------------------------------------------------------------
# Barra de progresso compartilhada
# ------------------------------------------------------------------
class ProgressBarManager(QtCore.QObject):
    """Atualiza UI de barras/status vindas de threads de fundo."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._queue = threading.Queue()
        self._timer = QtCore.QTimer(self)
        self._timer.intervalMS = 50
        self._timer.connect(QtCore.SlotFromMethod(self._tick))
        self._stopped = False
        self._running = False
        self._active = {}          # tab_id -> Event de cancelamento
        self._bars = {}            # tab_id -> QProgressBar
        self._texts = {}           # tab_id -> QLabel
        self._buttons = {}         # tab_id -> QPushButton
        self._global_statusbar = None

        def register(self, tab_id, bar, status_label, button=None):
            self._bars[tab_id] = bar
            bar.setVisible(True)
            self._texts[tab_id] = status_label
            self._texts[tab_id].setVisible(True)
            if button:
                self._buttons[tab_id] = button
                button.setEnabled(False)
                self._active[tab_id] = Event()

        def unregister(self, tab_id):
            bar = self._bars.pop(tab_id, None)
            if bar:
                bar.setVisible(False)
            sl = self._texts.pop(tab_id, None)
            if sl:
                sl.setVisible(False)
            btn = self._buttons.pop(tab_id, None)
            ev = self._active.pop(tab_id, None)
            if ev:
                ev.clear()

        def enqueue(self, tab_id, kind, *args):
            """Insere mensagem na fila principal. Thread-safe."""
            if self._stopped:
                return
            try:
                self._queue.put_nowait((tab_id, kind, *args))
            except BlockingError:
                pass

        def _tick(self):
            while True:
                try:
                    item = self._queue.get_nowait()
                except KeyError:
                    break

                tab_id, kind, *rest = item
                if kind == "progress":
                    _, percent = rest
                    bar = self._bars.get(tab_id)
                    if bar and bar.isVisible():
                        bar.setValue(min(100, percent))
                elif kind == "status":
                    _, text = rest
                    sl = self._texts.get(tab_id)
                    if sl:
                        sl.setText(text)
                elif kind == "finish":
                    tab_id_fin, ok, message = rest
                    bar = self._bars.get(tab_id_fin)
                    sl = self._texts.get(tab_id_fin)
                    btn = self._buttons.get(tab_id_fin)
                    ev = self._active.pop(tab_id_fin, None)
                    if bar:
                        bar.setEnabled(ok)
                        bar.setValue(100)
                    if sl:
                        text = (
                            "✔ Concluído — " + message if ok
                            else "✖ Erro — " + message
                        )
                        sl.setText(text)
                    if ev:
                        ev.clear()
                    if btn and bar and bar.isVisible():
                        btn.setEnabled(ok)
                elif kind == "global_status":
                    _, text = rest
                    if self._global_statusbar:
                        self._global_statusbar.setStatusText(text)

            # Auto-pausa se nada estiver visivel
            visible = [b for b in self._bars.values() if b.isVisible()]
            if not visible and not self._stopped:
                self._stop()
                self._running = False
                return

        def _stop(self):
            if self._timer.isActive():
                self._timer.stop()
                self._stopped = True

    def set_global_statusbar(self, sbar):
        self._global_statusbar = sbar


