# Trabalhador de conversao (video ou audio)
# ------------------------------------------------------------------
MEDIA_FMTS_VIDEO = {
    "mp4": {
        "vcodec": "libx264",
        "vopts": "-crf 23 -preset medium -profile:v high -level 4.0",
        "acodec": "aac",
        "abits": "192k",
        "container": "mp4",
    },
    "avi": {
        "vcodec": "mpeg4video",
        "acodec": "ac3",
        "abits": "192k",
        "container": "avi",
    },
    "ogv": {
        "container": "ogv",
    },
    "mkv": {
        "vcodec": "libx264",
        "vopts": "-crf 23 -preset medium",
        "acodec": "aac",
        "abits": "192k",
        "container": "mkv",
    },
    "mov": {
        "vcodec": "libx264",
        "vopts": "-crf 28 -preset veryslow",
        "acodec": "aac",
        "abits": "192k",
        "container": "mov",
    },
}


class MediaConversionWorker(QRunnable):
    """Converte media usando ffmpeg. Suporta video->audio e video->video."""
    finished = QtCore.Signal(bool, str)

    def __init__(self, input_path, output_path, fmt, tab_id, manager,
                 video_output=True):
        super().__init__()
        self.input_path = Path(input_path)
        self.output_path = Path(output_path)
        self.fmt = fmt
        self.tab_id = tab_id
        self.manager = manager
        self.video_output = video_output
        self.cancel = Event()
        self._proc = None
        self._prev_line_pct = 0

    def run(self):
        if self.cancel.is_set():
            self.manager.enqueue(self.tab_id, "finish", False,
                                 "Tarefa cancelada pelo usuario.")
            return

        try:
            import subprocess
        except ImportError:
            self.manager.enqueue(self.tab_id, "finish", False,
                                 "subprocess nao disponivel.")
            return

        out_dir = str(self.output_path.with_suffix("").parent)
        if not Path(out_dir).exists():
            try:
                Path(out_dir).mkdir(parents=True, exist_ok=True)
            except OSError:
                self.manager.enqueue(self.tab_id, "finish", False,
                                     f"Pasta de saida inacessivel: {out_dir}")
                return

        try:
            cmd = self._build_cmd()
            if not cmd:
                self.manager.enqueue(self.tab_id, "finish", False,
                                     "Comando de conversao inválido.")
                return
            self._proc = subprocess.Popen(
                cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, text=True)
        except Exception as e:
            self.manager.enqueue(self.tab_id, "finish", False,
                                 f"Erro ao iniciar ffmpeg: {e}")
            return

        try:
            while not self._proc.poll() and not self.cancel.is_set():
                line = self._proc.stderr.readline()
                if not line:
                    break
                new_pct = self._parse_line(line, self._prev_line_pct)
                self._prev_line_pct = new_pct

            if self.cancel.is_set():
                try:
                    self._proc.terminate()
                except Exception:
                    pass
                try:
                    self._proc.wait(timeout=10)
                except Exception:
                    self._proc.kill()
                    self._proc.wait()
        except KeyboardInterrupt:
            self._proc.terminate()
            try:
                self._proc.wait(timeout=10)
            except Exception:
                self._proc.kill()
                self._proc.wait()
            self.cancel.clear()
        finally:
            try:
                self._proc.communicate()
            except Exception:
                pass
            try:
                err = self._proc.stderr.read().decode(errors="replace")
            except Exception:
                err = ""
            rc = self._proc.returncode
            if rc != 0:
                raise RuntimeError(err)

            rel = ""
            if self.output_path.is_relative_to(Path.cwd()):
                rel = str(self.output_path.relative_to(Path.cwd()))
            else:
                rel = str(self.output_path)
            self.success = True
            self.msg = f"OK — {rel}"

        except Exception as e:
            self.success = False
            self.msg = str(e)

        finally:
            self.manager.enqueue(self.tab_id, "finish",
                                self.success, self.msg if self.msg else
                                "Conversao concluida.")

    def _build_cmd(self):
        """Monta o comando do ffmpeg conforme o formato."""
        cmd = ["ffmpeg", "-hide_banner", "-loglevel", "quiet", "-y",
               "-i", str(self.input_path)]

        if self.video_output:
            info = MEDIA_FMTS_VIDEO.get(self.fmt)
            if not info:
                return []
            cmd += ["-c:v", info["vcodec"]]
            if info.get("vopts"):
                cmd += info["vopts"].split()
            cmd += ["-c:a", info["acodec"]]
            if info.get("abits"):
                cmd += [info["abits"]]
            cmd += ["-f", info["container"], str(self.output_path)]
            return cmd

        # --- audio ---
        if self.fmt == "mp3":
            cmd += ["-vn", "-c:a", "libmp3lame", "-b:a", "192k", str(self.output_path)]
        elif self.fmt == "wav":
            cmd += ["-vn", "-c:a", "pcm_s24le", str(self.output_path)]
        elif self.fmt == "ogg":
            cmd += ["-vn", "-c:a", "libvorbis", "-q:a", "5", str(self.output_path)]
        elif self.fmt == "aac":
            cmd += ["-vn", "-c:a", "aac", "-b:a", "192k", str(self.output_path)]
        elif self.fmt == "alac":
            cmd += ["-c:a", "alac", str(self.output_path)]
        else:
            return []
        return cmd

    def _parse_line(self, line, last_pct):
        """Analisa uma linha do stderr do ffmpeg e informa progresso/status."""
        prog = PROG_RE.search(line)
        pct = 0
        if prog:
            pct = int(prog.group(1))

        # recalcula a partir de bytes restante/total
        if pct < 100:
            rm = REM_RE.search(line)
            if rm:
                try:
                    num = float(rm.group(1))
                    den = float(rm.group(2))
                    if den > 0:
                        pct = min(100, round((den - num) / den * 100))
                except ValueError:
                    pass

        status = ""
        tm = TIME_RE.search(line)
        if tm:
            s = int(tm.group(2)) * 60 + int(tm.group(3))
            m = int(tm.group(1)) * 60 + s
            status = f"Restam {m // 60:d}:{m % 60:02d}"
        fm = FRAMES_RE.search(line)
        if fm:
            status = f"Frames: {fm.group(1)} | {status}"

        if status:
            self.manager.enqueue(self.tab_id, "status", status)

        if pct != last_pct:
            self.manager.enqueue(self.tab_id, "progress", pct)
            self._prev_line_pct = pct

        return self._prev_line_pct


# ------------------------------------------------------------------
# Trabalhador de preview de qualidades (yt-dlp)
# ------------------------------------------------------------------
class QualityPreviewWorker(QRunnable):
    """Busca resolucoes disponiveis sem baixar o video."""
    qualities_ready = QtCore.Signal(int, str, list)
    finished = QtCore.Signal(bool, str)

    def __init__(self, url, tab_id, manager):
        super().__init__()
        self.url = url
        self.tab_id = tab_id
        self.manager = manager
        self._ydl = None

    def run(self):
        try:
            import yt_dlp
        except ImportError:
            self.finished.emit(False,
                               "yt-dlp nao instalado. Instale com: pip install yt-dlp")
            return

        ydl_opts = {
            "quiet": True,
            "no_warnings": True,
            "skip_download": True,
            "update_in_cache": False,
            "ignoreerrors": True,
            "continuedlistas": [],
        }
        ydl = yt_dlp.YoutubeDL(ydl_opts)

        try:
            info = ydl.extract_info(self.url, process=True)
        except Exception as e:
            self.finished.emit(False, f"Erro ao buscar informacoes: {e}")
            return

        if info is None or not info.get("formats"):
            self.finished.emit(False, "Nenhuma resolucao disponivel.")
            return

        formats = info["formats"]
        sorted_formats = sorted(formats, key=lambda f: f.get("height", 0))

        chosen_label = None
        chosen_stream = None
        for label, max_h in ALLOWED_QUALITIES:
            candidates = [f for f in sorted_formats if f.get("height") <= max_h]
            exact = [
                f for f in candidates
                if (f.get("resolution") or "") == label
                or label in (f.get("string") or "")
            ]
            if exact:
                chosen_stream = max(
                    exact,
                    key=lambda f: f.get("average_bitrate", 0) or f.get("width", 0),
                )
                chosen_label = chosen_stream.get("resolution")
                break
            else:
                chosen_stream = max(
                    candidates,
                    key=lambda f: f.get("average_bitrate", 0) or f.get("width", 0),
                )
                chosen_label = chosen_stream.get("resolution")

        if chosen_label is None:
            best = max(
                sorted_formats,
                key=lambda f: f.get("average_bitrate", 0) or f.get("width", 0),
            )
            chosen_label = best.get("resolution")
            chosen_stream = best

        infos = []
        for f in sorted(sorted_formats, key=lambda f: f.get("height", 0)):
            h = f.get("height", 0)
            label = to_label_height(h)
            sz = f.get("average_size_bytes", 0) or 0
            bt = f.get("average_bitrate", 0) or 0
            infos.append({
                "label": label,
                "size": fmt_size(sz),
                "bitrate": fmt_bitrate(bt),
                "meta": (label, fmt_size(sz), fmt_bitrate(bt)),
            })

        self.qualities_ready.emit(
            self.tab_id,
            chosen_label if chosen_label else "(sem rotulo)",
            infos,
        )
        self.finished.emit(True,
                           f"Pronto! Escolha {chosen_label or '(qualidade automatica)'} acima.")


# ------------------------------------------------------------------
# Trabalhador de download de video
# ------------------------------------------------------------------
class DownloadWorker(QRunnable):
    finished = QtCore.Signal(bool, str)

    def __init__(self, url, chosen_label, output_dir, tab_id, manager):
        super().__init__()
        self.url = url
        self.chosen_label = chosen_label
        self.output_dir = Path(output_dir)
        self.tab_id = tab_id
        self.manager = manager
        self.output_path = None

    def run(self):
        try:
            import yt_dlp
        except ImportError:
            self.manager.enqueue(self.tab_id, "finish", False,
                                 "yt-dlp nao instalado.")
            return

        ydl_opts = {
            "quiet": True,
            "no_warnings": True,
            "write_subtitles": "off",
            "write_manifest": False,
            "skip_download": False,
            "update_in_cache": False,
            "ignoreerrors": True,
            "continuedlistas": [],
            "postprocessor_args": ["-f", "mp4"],
            "output_directory": str(self.output_dir),
            "output_template": "%(%(resolution)s)s_%(ext)s",
            "preferred_formats": [
                {"ext": "mp4", "resolution": self.chosen_label},
            ],
            "max_downloads": 1,
        }
        ydl = yt_dlp.YoutubeDL(ydl_opts)

        def on_progress(d):
            try:
                pct = float(d.get("downloadpercentage", 0))
                self.manager.enqueue(self.tab_id, "progress", pct)
            except Exception:
                pass

        ydl.add_hook("progress", on_progress)

        try:
            outcome = ydl.extract(self.url, overwrite=True)
        except Exception as e:
            self.manager.enqueue(self.tab_id, "finish", False, str(e))
            return

        files = outcome.get("downloaded_files", [])
        if not files:
            self.manager.enqueue(self.tab_id, "finish", False,
                                 "Nenhum arquivo baixado. Verifique o link ou tente outra qualidade.")
            return

        try:
            fp = Path(files[0]).resolve()
            self.output_path = fp
            sz = fp.stat().st_size
            self.manager.enqueue(self.tab_id, "finish", True,
                                 f"Salvo como {fp.name} ({sz:,} bytes)")
        except Exception as e:
            self.manager.enqueue(self.tab_id, "finish", False,
                                 f"Erro ao acessar o arquivo: {e}")
except Exception as e:
    self.manager.enqueue(self.tab_id, "finish", False, str(e))


# ------------------------------------------------------------------
# Aba de conversao reutilizavel
# ------------------------------------------------------------------
class ConversionTab(QtWidgets.QWidget):
    def __init__(self, parent, tab_id, manager, video_output, title):
        super().__init__(parent)
        self.parent = parent
        self.tab_id = tab_id
        self.manager = manager
        self.video_output = video_output
        self.current_input = ""
        self._prev_worker = None

        self.forms = QtWidgets.QFormLayout(self)
        self.setMinimumWidth(620)

        # ---------- Entrada ----------
        self.lbl_input = QtWidgets.QLabel("Arquivo de entrada:")
        self_inp = QtWidgets.QPathEdit("")
        self.btn_input = QtWidgets.QPushButton("Selecionar arquivo")

        row1 = QtWidgets.QHBoxLayout()
        row1.addWidget(self.lbl_input)
        row1.addWidget(self_inp)
        row1.addWidget(self.btn_input)
        self.forms.addRow(self.lbl_input, self_inp, self.btn_input)

        # ---------- Formato ----------
        self.cmb_fmt = QtWidgets.QComboBox()
        self.cmb_fmt.addItem("-- Escolha um formato --")
        if video_output:
            for fmt in VIDEO_EXT:
                self.cmb_fmt.addItem(fmt.capitalize())
        else:
            for fmt in AUDIO_EXT:
                self.cmb_fmt.addItem(fmt.capitalize())
        self.forms.addRow(self.lbl_input, self.cmb_fmt)

        # ---------- Pasta de saida ----------
        self.lbl_outdir = QtWidgets.QLabel(str(CONVERT_OUT))
        self_inp_dir = QtWidgets.QPathEdit(str(CONVERT_OUT))
        self.btn_out = QtWidgets.QPushButton("Alterar pasta")

        row2 = QtWidgets.QHBoxLayout()
        row2.addWidget(self.lbl_outdir)
        row2.addWidget(self_inp_dir)
        row2.addWidget(self.btn_out)
        self.forms.addRow(self.lbl_outdir, self_inp_dir, self.btn_out)

        # ---------- Controle de progresso ----------
        self.pBar = QtWidgets.QProgressBar()
        self.pBar.setMaximumHeight(20)
        self.pBar.setStyleSheet(
            "QProgressBar { background-color: #ececec; border: 1px solid #bbbbbb; } "
            "QProgressBar::chunk { background-color: #1565c0; }"
        )
        self.lbl_status = QtWidgets.QLabel("Aguarde...")
        self.btn_conv = QtWidgets.QPushButton("Converter")

        ctrl = QtWidgets.QHBoxLayout()
        ctrl.addWidget(self.pBar)
        ctrl.addWidget(self.lbl_status)
        ctrl.addWidget(self.btn_conv)
        self.forms.addLast(ctrl)

        # Conexoes
        self.btn_input.clicked.connect(self._load_input)
        self.btn_out.clicked.connect(self._choose_output_dir)
        self.btn_conv.clicked.connect(self._on_convert)
        self_inp_dir.textChanged.connect(lambda: self._update_label())
        self._update_label()

        # Status bar global
        sbar = self.parent().statusBar()
        if not sbar:
            self.parent().setStatusBar(QtWidgets.QStatusBar())
            sbar = self.parent().statusBar()
        self.st_status = QtWidgets.QLabel("Aguarde...")
        sbar.widgets().append(self.st_status)
        sbar.addWidget(self.st_status, 0, 1)

        self.setWindowTitle(title)

    def _update_label(self):
        text = self_inp_dir.text() or str(CONVERT_OUT)
        self.lbl_outdir.setText(text)

    def _load_input(self):
        f, ok = QtWidgets.QFileDialog.getOpenFileName(
            self, "Selecionar mídia",
            str(HOME / "Desktop"),
            "Todos os Arquivos|*.*",
        )
        if not ok or not f:
            return
        self.current_input = f
        self_inp.setText(f)
        self_inp_dir.setText(str(CONVERT_OUT))
        self.lbl_outdir.setText(str(CONVERT_OUT))

    def _choose_output_dir(self):
        p = QtWidgets.QFileDialog.getExistingDirectory(
            self, "Pasta de saida", str(CONVERT_OUT))
        if not p:
            return
        self_inp_dir.setText(p)
        self.lbl_outdir.setText(p)

    def _get_output_path(self, input_path, fmt):
        out = Path(str(input_path).rsplit("/", 1)[0])
        if fmt in AUDIO_EXT:
            ext = "." + AUDIO_EXT[fmt]
        elif fmt in VIDEO_EXT:
            ext = VIDEO_EXT[fmt]
        else:
            ext = input_path.suffix.lower() or ".wav"
        return out.with_suffix(ext)

    def _on_convert(self):
        if not hasattr(self, "current_input") or not self.current_input:
            self.showStatusWarning("Nenhum arquivo de entrada selecionado.")
            return

        fmt = self.cmb_fmt.currentText().strip()
        if not fmt or fmt.startswith("--"):
            self.showStatusWarning("Selecione um formato de saida.")
            return

        input_path = Path(self.current_input)
        if not input_path.exists():
            self.showStatusWarning("Arquivo de entrada nao existe.")
            return

        out_dir = Path(self_inp_dir.text()).resolve()
        if not out_dir.is_dir():
            try:
                out_dir.mkdir(parents=True, exist_ok=True)
            except OSError:
                self.showStatusWarning(f"Pasta de saida nao escrita: {out_dir}")
                return

        output_path = self._get_output_path(input_path, fmt)
        self._start_worker(fmt, str(out_dir), video_output=self.video_output)

    def _start_worker(self, fmt, output_dir, video_output=True):
        """Inicia uma tarefa de conversao na thread principal."""
        if self._prev_worker is not None and self._prev_worker.isRunning():
            try:
                self._prev_worker.thread().requestIntervention(
                    QtCore.QThread.InterventionAbort
                )
            except Exception:
                pass
            self.showStatusWarning("Ja ha uma conversao em andamento. Aguarde concluir.")
            return

        worker_cls = MediaConversionWorker
        worker = worker_cls(
            input_path=self.current_input,
            output_path=self._get_output_path(Path(self.current_input), fmt),
            fmt=fmt,
            tab_id=self.tab_id,
            manager=self.manager,
            video_output=video_output,
        )

        evt = self.manager._active.get(self.tab_id)
        if evt and evt.is_set():
            # ja havia outro worker iniciado antes; ignorar
            pass

        t = QtCore.QThread(self.manager)
        worker.setThread(t)
        t.start()

        self._prev_worker = worker
        self.manager._active[self.tab_id] = worker.cancel
        self.manager.register(self.tab_id, self.pBar, self.lbl_status, self.btn_conv)
        self.btn_conv.setEnabled(False)
        self.pBar.setVisible(True)
        self.pBar.setValue(0)
        self.lbl_status.setText("Conversao em andamento...")

        def finished(tab_id, ok, msg):
            self.manager.unregister(tab_id)
            self._prev_worker = None
            self.manager._active.pop(tab_id, None)
            self.btn_conv.setEnabled(True)
            self.pBar.setVisible(False)
            self.pBar.setValue(0)
            self.lbl_status.setText("")
            if ok:
                self.showStatusInfo(f"Sucesso: {msg}")
            # Limpa barra de status
            sbar = self.parent().statusBar()
            if sbar:
                sbar.setStatusText("")
                timer = QtCore.QTimer(self.parent())
                timer.singleShotStartupDelay(300)
                timer.timeout.connect(lambda: sbar.setStatusText(""))
                timer.start(3500)

        worker.finished.connect(finished)

    def showStatusWarning(self, msg):
        sbar = self.parent().statusBar()
        if sbar:
            sbar.setStatusText(f"⚠ {msg}")
            timer = QtCore.QTimer(self.parent())
            timer.singleShotStartupDelay(800)
            timer.timeout.connect(lambda: sbar.setStatusText(""))
            timer.start(4000)

    def showStatusError(self, msg):
        self.showStatusWarning(msg)

    def showStatusInfo(self, msg):
        sbar = self.parent().statusBar()
        if sbar:
            sbar.setStatusText(msg)
            timer = QtCore.QTimer(self.parent())
            timer.singleShotStartupDelay(800)
            timer.timeout.connect(lambda: sbar.setStatusText(""))
            timer.start(4000)


