class TabBaixar(QtWidgets.QWidget):
    def __init__(self, parent, manager):
        super().__init__(parent)
        self.parent = parent
        self.manager = manager
        self.tab_id = "download"

        # URL
        self.url_input = QtWidgets.QLineEdit(
            "https://www.youtube.com/watch?v=dQw4w9WgXcQ"
        )

        # Tabela de qualidades
        self.tbl_quals = QtWidgets.QTableWidget()
        self.tbl_quals.setContextMenuPolicy(QtWidgets.QContextMenuPolicy.NoContextmenu)
        self.tbl_quals.verticalScrollBar().setMaxValue(1000)
        self.tbl_quals.doubleClicked.connect(self._on_row_double_click)

        # Botao para escolher pasta de destino
        self.btn_sel_out = QtWidgets.QPushButton("Escolher pasta de destino")
        self.btn_sel_out.setPropertyPath(str(VIDEO_DL_OUT))

        # Label da pasta
        self.lbl_dl_out = QtWidgets.QLabel(str(VIDEO_DL_OUT))

        # Layout principal
        main = QtWidgets.QVBoxLayout(self)
        main.addWidget(QtWidgets.QLabel("Cole o link do video:"))
        main.addWidget(self.url_input)
        main.addSpacing(6)
        main.addWidget(self.lbl_dl_out)
        main.addSpacing(6)
        btn_row = QtWidgets.QHBoxLayout()
        btn_row.addWidget(QtWidgets.QLabel("Pasta de saída:"))
        btn_row.addWidget(self.btn_sel_out)
        main.addLayout(btn_row)
        main.addSpacing(10)

        btn_search = QtWidgets.QPushButton("Buscar qualidades")
        btn_search.clicked.connect(self._on_buscar_qualidades)
        main.addWidget(btn_search)
        main.addSpacing(10)
        main.addWidget(self.tbl_quals)
        main.addStretch()

        # Status especifico desta aba
        sbar = self.parent().statusBar()
        if sbar:
            sbar.widgets().append(QtWidgets.QLabel("Aguarde..."))

        self.st_tab = QtWidgets.QLabel("Aguarde...")
        sbar.widgets().append(self.st_tab)
        self.manager.enqueue(self.tab_id, "global_status", "Aguarde...")

    def _on_buscar_qualidades(self):
        url = self.url_input.text().strip()
        if not url:
            self.showStatusWarning("Cole um URL valido.")
            return

        worker = QualityPreviewWorker(url, self.tab_id, self.manager)
        t = QtCore.QThread(self.manager)
        worker.setThread(t)
        t.start()

        worker.qualities_ready.connect(
            lambda tab_id, label, infos: self._fill_table(label, infos)
        )
        worker.finished.connect(self._on_preview_finished)

        self.st_tab.setText("Buscando qualidades...")
        if self.tbl_quals.model():
            self.tbl_quals.clear()

    def _on_preview_finished(self, ok, msg):
        self.st_tab.setText("")
        if not ok:
            self.st_tab.setText(msg)
            if self.tbl_quals.model():
                self.tbl_quals.clear()

    def _fill_table(self, label, infos):
        """Preenche a tabela com as qualidades permitidas."""
        rows = []
        order = [l for l, _ in ALLOWED_QUALITIES]
        seen = set()
        for l in order:
            if l in seen:
                continue
            seen.add(l)
            max_h = [h for _, h in ALLOWED_QUALITIES if _ == l][0]
            candidates = [f for f in infos if f.get("height") <= max_h]
            exact = [
                f for f in candidates
                if (f.get("resolution") or "") == l
                or l in (f.get("string") or "")
            ]
            if exact:
                chosen = max(
                    exact,
                    key=lambda f: f.get("average_bitrate", 0) or f.get("width", 0),
                )
                rows.append({
                    "label": l,
                    "size": fmt_size(chosen.get("average_size_bytes", 0)),
                    "bitrate": fmt_bitrate(chosen.get("average_bitrate", 0)),
                    "meta": (
                        l,
                        fmt_size(chosen.get("average_size_bytes", 0)),
                        fmt_bitrate(chosen.get("average_bitrate", 0)),
                    ),
                })
            else:
                best = max(
                    candidates,
                    key=lambda f: f.get("average_bitrate", 0) or f.get("width", 0),
                )
                rows.append({
                    "label": l,
                    "size": fmt_size(best.get("average_size_bytes", 0)),
                    "bitrate": fmt_bitrate(best.get("average_bitrate", 0)),
                    "meta": (
                        l,
                        fmt_size(best.get("average_size_bytes", 0)),
                        fmt_bitrate(best.get("average_bitrate", 0)),
                    ),
                })

        if not rows:
            return

        model = QualityTableModel(rows)
        self.tbl_quals.clear()
        self.tbl_quals.setModel(model)

        # Destaca a linha da qualidade escolhida
        chosen = label
        if chosen in order:
            for ri, r in enumerate(rows):
                if r["label"] == chosen:
                    self.tbl_quals.setCurrentRow(ri)
                    self.tbl_quals.selectionModel().select(
                        ri, QtWidgets.QItemSelectionFlag.Current
                    )
                    break

    def _on_row_double_click(self, index):
        """Baixa o video conforme a resoluciao selecionada na tabela."""
        try:
            row = self.tbl_quals.rowForIndex(index)
            meta = self.tbl_quals.model().rowData(
                self.tbl_quals.indexForRow(row)
            )
            label = meta[0] if meta else ""
            worker = DownloadWorker(
                self.url_input.text(),
                label,
                self.download_dir(),
                self.tab_id,
                self.manager,
            )
            t = QtCore.QThread(self.manager)
            worker.setThread(t)
            t.start()
            self.st_tab.setText("Baixando...")
            self.manager.enqueue(self.tab_id, "global_status", "Baixando...")
            self.manager.enqueue(self.tab_id, "progress", 0)
        except Exception as e:
            self.showStatusWarning(str(e))

    def download_dir(self):
        p = self.btn_sel_out.getPropertyPath()
        if p:
            return str(Path(p))
        return str(VIDEO_DL_OUT)


# ------------------------------------------------------------------
# Janela principal
# ------------------------------------------------------------------
class MainWindow(QtWidgets.QMainWindow):
    def __init__(self):
        super().__init__()
        self.setMinimumSize(900, 700)
        self.manager = ProgressBarManager(self)
        self.manager.set_global_statusbar(
            self.statusBar() if self.statusBar() else None
        )
        self._tabs = []
        self._rebuildUi()
        self.showStatusBar()

    def _rebuildUi(self):
        central = QtWidgets.QWidget(self)
        main = QtWidgets QVBoxLayout(central)

        tab_widget = QtWidgets.QTabWidget(central)

        self._add_tab_baixar(tab_widget)
        self._add_tab_audio_audio(tab_widget)
        self._add_tab_video_video(tab_widget)

        main.addWidget(tab_widget)
        self.setCentralWidget(central)
        self.setWindowTitle("MultiFormat Media Converter")
        self.setFixedSize(980, 720)

    def _add_tab_baixar(self, tab_widget):
        tab = TabBaixar(self, self.manager)
        tab_widget.addTab(tab, "Baixar Vídeo")
        self._tabs.append(tab)

    def _add_tab_audio_audio(self, tab_widget):
        tab = ConversionTab(
            self, "audio_audio", self.manager,
            video_output=False, title="Áudio → Áudio",
        )
        tab_widget.addTab(tab, "Áudio → Áudio")
        self._tabs.append(tab)

    def _add_tab_video_video(self, tab_widget):
        tab = ConversionTab(
            self, "video_video", self.manager,
            video_output=True, title="Vídeo → Vídeo",
        )
        tab_widget.addTab(tab, "Vídeo → Vídeo")
        self._tabs.append(tab)


# ------------------------------------------------------------------
# Entrada principal
# ------------------------------------------------------------------
if __name__ == "__main__":
    app = QtWidgets QApplication(sys.argv)
    win = MainWindow()
    win.showMaximized()
    sys.exit(app.exec())
